//! The Markdown report, rendered from [`Results`] alone, so a report can be
//! regenerated from its JSON.

use std::fmt::Write as _;

use crate::corpus::Kind;
use crate::metrics::{Metrics, Tally};
use crate::results::{Config, CorpusInfo, Results, Row, Run, mode_name};

pub fn render(r: &Results) -> String {
    let mut o = String::new();
    let _ = writeln!(o, "# Ghostcaret replay benchmark\n");
    let _ = writeln!(
        o,
        "Generated by {} from `results.json` (schema {}). Prompt template version {}. Method and metrics: [docs/quality.md](../../docs/quality.md#benchmark) and `crates/bench/README.md`.\n",
        r.tool, r.schema, r.engine.prompt_template_version
    );
    let bold: Vec<f32> = boldness_values(r);
    summary(&mut o, r);
    method(&mut o, r);
    corpora(&mut o, r);
    runs(&mut o, r);
    let _ = writeln!(o, "## Results\n");
    let _ = writeln!(
        o,
        "Rates are pooled over a corpus's samples; \"all\" is the mean over the corpora. Savings count Tab and backtick as keystrokes. \"Wrong\" is the share of shown suggestions whose first Take Word unit was not what came next; wrong/100w is per 100 typed words.\n"
    );
    auto_sweep(&mut o, r, &bold);
    modes(&mut o, r);
    ceilings(&mut o, r, &bold);
    latency(&mut o, r);
    appendix(&mut o, r);
    o
}

fn boldness_values(r: &Results) -> Vec<f32> {
    let mut b: Vec<f32> = r
        .runs
        .iter()
        .flat_map(|run| run.rows.iter().map(|x| x.config.boldness))
        .collect();
    b.sort_by(f32::total_cmp);
    b.dedup();
    b
}

fn pct(x: f64) -> String {
    format!("{:.1} %", 100.0 * x)
}

fn kind_of(c: &CorpusInfo) -> Kind {
    match c.kind.as_str() {
        "chat" => Kind::Chat,
        "email" => Kind::Email,
        _ => Kind::Document,
    }
}

fn row<'a>(run: &'a Run, corpus: &str, f: impl Fn(&Config) -> bool) -> Option<&'a Row> {
    run.rows.iter().find(|x| x.corpus == corpus && f(&x.config))
}

/// Metrics of the matching row in each corpus, and their mean.
fn across(
    r: &Results,
    run: &Run,
    f: impl Fn(&Config, Kind) -> bool,
) -> (Vec<Option<Metrics>>, Option<Metrics>) {
    let per: Vec<Option<Metrics>> = r
        .corpora
        .iter()
        .map(|c| row(run, &c.id, |cfg| f(cfg, kind_of(c))).map(|x| x.metrics))
        .collect();
    let present: Vec<Metrics> = per.iter().flatten().copied().collect();
    (per, mean(&present))
}

fn mean(ms: &[Metrics]) -> Option<Metrics> {
    if ms.is_empty() {
        return None;
    }
    let n = ms.len() as f64;
    let avg = |f: fn(&Metrics) -> f64| ms.iter().map(f).sum::<f64>() / n;
    Some(Metrics {
        keystroke_savings: avg(|m| m.keystroke_savings),
        wrong_rate: avg(|m| m.wrong_rate),
        acceptance_rate: avg(|m| m.acceptance_rate),
        chars_per_accepted: avg(|m| m.chars_per_accepted),
        chars_per_shown: avg(|m| m.chars_per_shown),
        shown_per_100_words: avg(|m| m.shown_per_100_words),
        wrong_per_100_words: avg(|m| m.wrong_per_100_words),
        words_per_shown: avg(|m| m.words_per_shown),
        latency: Default::default(),
    })
}

fn summary(o: &mut String, r: &Results) {
    let _ = writeln!(o, "## Summary\n");
    let _ = writeln!(
        o,
        "The shipped default: Auto at boldness {} with the default ceiling of each category ({}). Savings / wrong rate.\n",
        r.engine.default_boldness,
        r.engine
            .default_ceilings
            .iter()
            .map(|(k, v)| format!("{k} {v}"))
            .collect::<Vec<_>>()
            .join(", ")
    );
    let mut head = "| Model | All |".to_owned();
    let mut rule = "| --- | --- |".to_owned();
    for c in &r.corpora {
        let _ = write!(head, " {} |", c.id);
        rule.push_str(" --- |");
    }
    let _ = writeln!(o, "{head}\n{rule}");
    for run in &r.runs {
        let (per, all) = across(r, run, |cfg, k| cfg.is_default(k));
        let cell = |m: Option<Metrics>| {
            m.map_or("–".into(), |m| {
                format!("{} / {}", pct(m.keystroke_savings), pct(m.wrong_rate))
            })
        };
        let _ = write!(o, "| {} | {} |", run.model.name, cell(all));
        for m in per {
            let _ = write!(o, " {} |", cell(m));
        }
        o.push('\n');
    }
    o.push('\n');
}

fn method(o: &mut String, r: &Results) {
    let p = &r.method.pause;
    let _ = writeln!(o, "## Method\n");
    let _ = writeln!(
        o,
        "Each sample is typed character by character into a simulated field. The product's own controller (`ghostcaret_engine::controller`) receives the field snapshots, key-gate events and pause timer a backend would send; its requests (prompt segments from `prompt::build`, stop rule from the settings and the app's category) run on the model with a `stop::Stopper`, and its cut (`stop::cut`) decides what is shown. Take Word, Take All and typing-through use the engine's `SuggestionView` methods, as the key gate does.\n"
    );
    let _ = writeln!(
        o,
        "- **Pause points.** A suggestion is requested and seen only where the typist pauses at least {:.0} ms (the {} ms pause plus the 100 ms latency target): at every word boundary, right after an accept, and inside words where a seeded log-normal inter-key interval (mean {:.2} ms from Dhakal et al., CHI 2018; σ of ln = {}; seed {}) is long enough, which is {:.1} % of positions inside words.",
        p.visible_ms,
        r.engine.pause_ms,
        p.mean_iki_ms,
        p.sigma,
        p.seed,
        100.0 * r.method.within_word_pause_rate
    );
    let _ = writeln!(
        o,
        "- **User.** Ideal but honest: takes the whole visible suggestion with one backtick when all of it is what comes next, otherwise takes Take Word units with Tab while each is what comes next, otherwise types the next character. \"What comes next\" also requires the suggestion to end where the real text has a unit end or boundary, so a fragment of a longer word is never accepted. Single-character accepts are typed instead (same cost)."
    );
    let _ = writeln!(
        o,
        "- **Keystrokes** are Unicode scalar values typed plus accept keys; dead keys and input-method composition are not modelled."
    );
    let _ = writeln!(
        o,
        "- **Context.** Chat and email samples have the earlier turns or the message being answered as the visible conversation (conversation context is on by default); document samples have the title and up to two earlier paragraphs above the caret. Clipboard, style memory and about-me are off, as by default."
    );
    let _ = writeln!(
        o,
        "- **Requests** ask for two alternatives as the product does with a local model; the user never cycles them, but an alternative is shown when the main candidate is silent (counted per row). Show More and prefill are not exercised.\n- **Shared generation.** Configurations differ only in their stop rule and decoding is greedy, so each distinct prompt is generated once with every configuration's stopper attached; each configuration gets the candidate cut back to where its own stopper stopped, which is what its own request returns (unit-tested). Its latency is the time at which its own stopper stopped. All configurations of a sample replay together and prompts reach the model in typing order, so its cache only appends, as while typing.\n- **Determinism.** Greedy decoding, fixed corpus slices, hashed pause draws, and a serving order that depends only on the replays. GPU kernels may still differ in the last bits between batch shapes.\n"
    );
}

fn corpora(o: &mut String, r: &Results) {
    let _ = writeln!(o, "## Corpora\n");
    let _ = writeln!(
        o,
        "| Id | Text | Language | Typed into | License | Samples | Words | Characters |\n| --- | --- | --- | --- | --- | --- | --- | --- |"
    );
    for c in &r.corpora {
        let _ = writeln!(
            o,
            "| {} | [{}]({}) | {} | {} (`{}`, {}) | [{}]({}) | {} | {} | {} |",
            c.id,
            c.name,
            c.source_url,
            c.language,
            c.app_name,
            c.app_id,
            c.kind,
            short_license(&c.license),
            c.license_url,
            c.samples,
            c.words,
            c.chars
        );
    }
    o.push('\n');
    for c in &r.corpora {
        let _ = writeln!(
            o,
            "**{}.** {} *License:* {} *Sampling:* {}\n",
            c.id, c.why, c.license, c.sampling
        );
    }
    let _ = writeln!(o, "<details><summary>Pinned files and SHA-256</summary>\n");
    for c in &r.corpora {
        for f in &c.files {
            let _ = writeln!(o, "- `{}` {} <{}>", f.sha256, c.id, f.url);
        }
    }
    let _ = writeln!(o, "\n</details>\n");
}

/// The license's name, before any explanation in parentheses or after a
/// colon.
fn short_license(l: &str) -> &str {
    l.split(['(', ':']).next().unwrap_or(l).trim()
}

fn runs(o: &mut String, r: &Results) {
    let _ = writeln!(o, "## Models and machine\n");
    let _ = writeln!(
        o,
        "| Model | File | SHA-256 | Size | llama.cpp | Backend | GPU layers | Load (1 min) | Latency |\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |"
    );
    for run in &r.runs {
        let m = &run.model;
        let _ = writeln!(
            o,
            "| {} | `{}` | `{}`{} | {:.2} GB | {} | {} | {} | {:.1} → max {:.1} | {} |",
            m.name,
            m.file,
            m.sha256,
            if m.sha256_verified { " ✓" } else { "" },
            m.size_bytes as f64 / 1e9,
            m.description,
            run.backend,
            if run.gpu_layers == u32::MAX {
                "all".into()
            } else {
                run.gpu_layers.to_string()
            },
            run.load1_start,
            run.load1_max,
            if run.latency_valid {
                "valid".to_owned()
            } else {
                format!("**invalid**: load above {}", run.max_load)
            }
        );
    }
    o.push('\n');
    let mut machines: Vec<String> = r
        .runs
        .iter()
        .map(|run| {
            let m = &run.machine;
            format!(
                "{}, {} threads, {} GB RAM; GPU: {}; {} (kernel {})",
                m.cpu,
                m.threads,
                m.ram_gb,
                if m.gpu.is_empty() { "none" } else { &m.gpu },
                m.os,
                m.kernel
            )
        })
        .collect();
    machines.dedup();
    for m in machines {
        let _ = writeln!(o, "Machine: {m}.\n");
    }
    let _ = writeln!(o, "✓: the file's SHA-256 equals the curated manifest's.\n");
    for run in &r.runs {
        let limited: Vec<String> = r
            .corpora
            .iter()
            .filter_map(|c| {
                let n = run.samples.get(&c.id).copied().unwrap_or(0);
                (n < c.samples).then(|| format!("{} {} of {}", c.id, n, c.samples))
            })
            .collect();
        let _ = writeln!(
            o,
            "- {}: started {}, {:.0} min, {} generations, {} tokens, n_ctx {}, {} threads{}.",
            run.model.name,
            run.started,
            run.wall_s / 60.0,
            run.generations,
            run.tokens,
            run.n_ctx,
            run.threads,
            if limited.is_empty() {
                String::new()
            } else {
                format!("; **subset**: {}", limited.join(", "))
            }
        );
    }
    o.push('\n');
}

const HEAD: &str =
    "| Savings | Wrong | Accepted | Chars/accepted | Shown/100w | Wrong/100w | Words/shown |";
const RULE: &str = " --- | --- | --- | --- | --- | --- | --- |";

fn cells(m: &Metrics) -> String {
    format!(
        " {} | {} | {} | {:.1} | {:.1} | {:.1} | {:.1} |",
        pct(m.keystroke_savings),
        pct(m.wrong_rate),
        pct(m.acceptance_rate),
        m.chars_per_accepted,
        m.shown_per_100_words,
        m.wrong_per_100_words,
        m.words_per_shown
    )
}

/// Picks the configurations one table row covers.
type Filter = Box<dyn Fn(&Config, Kind) -> bool>;
/// A labelled row of a results table and the configurations it covers.
type TableRow = (String, Filter);

/// A table per corpus plus "all": `rows` gives a label and a config filter.
fn per_corpus(o: &mut String, r: &Results, first: &str, rows: &[TableRow]) {
    let mut ids: Vec<Option<&CorpusInfo>> = vec![None];
    ids.extend(r.corpora.iter().map(Some));
    for c in ids {
        let _ = writeln!(
            o,
            "**{}**\n",
            c.map_or("All corpora (mean)", |c| c.id.as_str())
        );
        let _ = writeln!(o, "| Model | {first} {HEAD}\n| --- | --- |{RULE}");
        for run in &r.runs {
            for (label, f) in rows {
                let m = match c {
                    None => across(r, run, |cfg, k| f(cfg, k)).1,
                    Some(c) => row(run, &c.id, |cfg| f(cfg, kind_of(c))).map(|x| x.metrics),
                };
                if let Some(m) = m {
                    let _ = writeln!(o, "| {} | {label} |{}", run.model.name, cells(&m));
                }
            }
        }
        o.push('\n');
    }
}

fn auto_sweep(o: &mut String, r: &Results, bold: &[f32]) {
    let _ = writeln!(o, "### Auto: boldness sweep at the default ceilings\n");
    let rows: Vec<TableRow> = bold
        .iter()
        .map(|&b| {
            let f: Filter = Box::new(move |c: &Config, k| {
                c.ceiling == Some(crate::results::default_ceiling(k)) && c.boldness == b
            });
            (format!("{b:.2}"), f)
        })
        .collect();
    per_corpus(o, r, "Boldness |", &rows);
}

fn modes(o: &mut String, r: &Results) {
    let b = r.engine.default_boldness;
    let _ = writeln!(o, "### Length modes at boldness {b}\n");
    let mut rows: Vec<TableRow> = Vec::new();
    for mode in ["word", "phrase", "sentence"] {
        rows.push((
            mode.into(),
            Box::new(move |c: &Config, _| {
                c.ceiling.is_none() && mode_name(c.mode) == mode && c.boldness == b
            }),
        ));
    }
    rows.push((
        "auto (default ceiling)".into(),
        Box::new(move |c: &Config, k| {
            c.ceiling == Some(crate::results::default_ceiling(k)) && c.boldness == b
        }),
    ));
    per_corpus(o, r, "Mode |", &rows);
}

fn ceilings(o: &mut String, r: &Results, bold: &[f32]) {
    let _ = writeln!(o, "### Auto ceilings\n");
    let _ = writeln!(
        o,
        "Savings / wrong rate of Auto with each ceiling; **bold** marks the current default ceiling.\n"
    );
    let mut ceils: Vec<String> = r
        .runs
        .iter()
        .flat_map(|run| {
            run.rows
                .iter()
                .filter_map(|x| x.config.ceiling.map(mode_name))
        })
        .map(str::to_owned)
        .collect();
    ceils.sort_by_key(|c| {
        ["word", "phrase", "sentence", "paragraph"]
            .iter()
            .position(|x| x == c)
    });
    ceils.dedup();
    for c in &r.corpora {
        let default = mode_name(crate::results::default_ceiling(kind_of(c)));
        let _ = writeln!(o, "**{}** ({})\n", c.id, c.kind);
        let mut head = "| Model | Boldness |".to_owned();
        let mut rule = "| --- | --- |".to_owned();
        for ceil in &ceils {
            if ceil == default {
                let _ = write!(head, " **≤{ceil}** |");
            } else {
                let _ = write!(head, " ≤{ceil} |");
            }
            rule.push_str(" --- |");
        }
        let _ = writeln!(o, "{head}\n{rule}");
        for run in &r.runs {
            for &b in bold {
                let _ = write!(o, "| {} | {b:.2} |", run.model.name);
                for ceil in &ceils {
                    let m = row(run, &c.id, |cfg| {
                        cfg.ceiling.map(mode_name) == Some(ceil.as_str()) && cfg.boldness == b
                    });
                    match m {
                        Some(x) => {
                            let _ = write!(
                                o,
                                " {} / {} |",
                                pct(x.metrics.keystroke_savings),
                                pct(x.metrics.wrong_rate)
                            );
                        }
                        None => o.push_str(" – |"),
                    }
                }
                o.push('\n');
            }
        }
        o.push('\n');
    }
}

fn latency(o: &mut String, r: &Results) {
    let _ = writeln!(o, "### Time to suggestion\n");
    let _ = writeln!(
        o,
        "Request to finished completion at the default configuration, over all corpora. Prefill is not exercised, and a configuration's requests may reuse a generation another configuration started, so these are not product traces. Runs marked invalid were taken under load and say nothing about the product's latency.\n"
    );
    let _ = writeln!(
        o,
        "| Model | Requests | p50 | p95 | Valid |\n| --- | --- | --- | --- | --- |"
    );
    for run in &r.runs {
        // Latencies are summarised per row; pool by request-weighted rows.
        let rows: Vec<&Row> = r
            .corpora
            .iter()
            .filter_map(|c| row(run, &c.id, |cfg| cfg.is_default(kind_of(c))))
            .collect();
        let n: usize = rows.iter().map(|x| x.metrics.latency.requests).sum();
        let w = |f: fn(&Row) -> f64| {
            if n == 0 {
                0.0
            } else {
                rows.iter()
                    .map(|x| f(x) * x.metrics.latency.requests as f64)
                    .sum::<f64>()
                    / n as f64
            }
        };
        let _ = writeln!(
            o,
            "| {} | {} | {:.0} ms | {:.0} ms | {} |",
            run.model.name,
            n,
            w(|x| x.metrics.latency.p50_ms),
            w(|x| x.metrics.latency.p95_ms),
            if run.latency_valid {
                "yes"
            } else {
                "**no** (under load)"
            }
        );
    }
    let _ = writeln!(
        o,
        "\nPercentiles are per corpus, averaged weighted by requests.\n"
    );
}

fn appendix(o: &mut String, r: &Results) {
    let _ = writeln!(o, "## All results\n");
    let _ = writeln!(
        o,
        "| Model | Corpus | Config | Boldness | Savings | Wrong | Accepted | Chars/accepted | Shown/100w | Wrong/100w | Words/shown | Requests | From alternative | p50 | p95 |\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |"
    );
    for run in &r.runs {
        for x in &run.rows {
            let m = &x.metrics;
            let t: &Tally = &x.tally;
            let _ = writeln!(
                o,
                "| {} | {} | {} | {:.2} |{} {} | {} | {:.0} ms | {:.0} ms |",
                run.model.name,
                x.corpus,
                x.config.label(),
                x.config.boldness,
                cells(m),
                t.requests,
                t.from_alternative,
                m.latency.p50_ms,
                m.latency.p95_ms
            );
        }
    }
    o.push('\n');
}
